211	/// Resolves authentication from config settings.
212	pub fn resolve_auth(
213	    auth_type: &str,
214	    token_env: &str,
215	    header: Option<&str>,
216	    env_vars: &HashMap<String, String>,
217	) -> Option<AuthHeader> {
218	    // First check the provided env_vars map, then fall back to system env
219	    let token = env_vars
220	        .get(token_env)
221	        .cloned()
222	        .or_else(|| std::env::var(token_env).ok())?;
223	
224	    match auth_type {
225	        "bearer" => Some(AuthHeader::bearer(&token)),
226	        "header" => {
227	            let header_name = header.unwrap_or("X-Auth-Token");
228	            Some(AuthHeader::custom(header_name, &token))
229	        }
230	        _ => None,
231	    }
232	}
