68	    /// Resolve extends with a trust checker.
69	    ///
70	    /// The `trust_check` closure is called for each URL before it is fetched.
71	    /// It should return `Ok(())` if the URL is trusted, or an error to abort.
72	    /// This enables the caller to prompt the user, check a trust store, or
73	    /// reject untrusted URLs based on the current trust policy.
74	    pub fn resolve_with_trust<F>(
75	        &self,
76	        config: &BivvyConfig,
77	        trust_check: &mut F,
78	    ) -> Result<BivvyConfig>
79	    where
80	        F: FnMut(&str) -> Result<()>,
81	    {
82	        self.resolve_with_visited(config, &mut HashSet::new(), 0, trust_check)
83	    }
84	
85	    fn resolve_with_visited<F>(
86	        &self,
87	        config: &BivvyConfig,
88	        visited: &mut HashSet<String>,
89	        depth: usize,
90	        trust_check: &mut F,
91	    ) -> Result<BivvyConfig>
92	    where
93	        F: FnMut(&str) -> Result<()>,
94	    {
95	        if depth > self.max_depth {
96	            return Err(anyhow!(
97	                "Config extends depth exceeds maximum of {}",
98	                self.max_depth
99	            ));
100	        }
101	
102	        // If no extends, return config as-is
103	        let extends = match &config.extends {
104	            Some(e) if !e.is_empty() => e,
105	            _ => return Ok(config.clone()),
106	        };
107	
108	        // Convert current config to Value for merging
109	        let config_value = serde_yaml::to_value(config)?;
110	
111	        // Environment override blocks should replace entirely, not field-merge
112	        let leaf_keys = std::collections::HashSet::from(["environments"]);
113	
114	        // Start with empty Value
115	        let mut merged = serde_yaml::Value::Mapping(serde_yaml::Mapping::new());
116	
117	        // Process each base config in order
118	        for ext in extends {
119	            // Check for cycles
120	            if visited.contains(&ext.url) {
121	                return Err(anyhow!("Circular extends detected: {}", ext.url));
122	            }
123	            visited.insert(ext.url.clone());
124	
125	            // Check trust before fetching
126	            trust_check(&ext.url)?;
127	
128	            // Fetch and parse base config
129	            let content = self.fetcher.fetch(&ext.url)?;
130	            let base_config: BivvyConfig = serde_yaml::from_str(&content)?;
131	
132	            // Recursively resolve base's extends
133	            let resolved_base =
134	                self.resolve_with_visited(&base_config, visited, depth + 1, trust_check)?;
135	
136	            // Convert to Value and merge
137	            let base_value = serde_yaml::to_value(&resolved_base)?;
138	            merged = deep_merge_with_leaves(&merged, &base_value, &leaf_keys);
139	        }
140	
141	        // Finally merge the current config on top
142	        let final_value = deep_merge_with_leaves(&merged, &config_value, &leaf_keys);
143	
144	        // Deserialize back to BivvyConfig
145	        let mut final_config: BivvyConfig = serde_yaml::from_value(final_value)?;
146	
147	        // Clear extends from final config (already resolved)
148	        final_config.extends = None;
149	
150	        Ok(final_config)
151	    }
