1	//! Remote configuration fetching.
2	//!
3	//! This module provides functionality for fetching configuration files
4	//! from remote URLs.
5	
6	use anyhow::{anyhow, Context, Result};
7	use std::collections::HashMap;
8	use std::path::PathBuf;
9	use std::time::Duration;
10	
11	/// Fetches remote configuration files with caching.
12	///
13	/// # Example
14	///
15	/// ```no_run
16	/// use bivvy::config::RemoteFetcher;
17	/// use std::time::Duration;
18	///
19	/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
20	///
21	/// // Fetch a remote config file
22	/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
23	/// ```
24	pub struct RemoteFetcher {
25	    /// Request timeout.
26	    timeout: Duration,
27	    /// Cache directory for downloaded configs.
28	    cache_dir: PathBuf,
29	    /// HTTP client.
30	    client: reqwest::blocking::Client,
31	}
32	
33	impl RemoteFetcher {
34	    /// Create a fetcher with the specified timeout.
35	    pub fn new(timeout: Duration) -> Self {
36	        let cache_dir = crate::sys::cache_dir()
37	            .unwrap_or_else(|| PathBuf::from("~/.cache"))
38	            .join("bivvy")
39	            .join("remote-configs");
40	
41	        Self {
42	            timeout,
43	            cache_dir,
44	            client: reqwest::blocking::Client::builder()
45	                .timeout(timeout)
46	                .build()
47	                .expect("Failed to create HTTP client"),
48	        }
49	    }
50	
51	    /// Create a fetcher with a custom cache directory.
52	    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
53	        Self {
54	            timeout,
55	            cache_dir,
56	            client: reqwest::blocking::Client::builder()
57	                .timeout(timeout)
58	                .build()
59	                .expect("Failed to create HTTP client"),
60	        }
61	    }
62	
63	    /// Fetch a configuration file from a URL.
64	    pub fn fetch(&self, url: &str) -> Result<String> {
65	        // Check cache first
66	        if let Some(cached) = self.check_cache(url)? {
67	            return Ok(cached);
68	        }
69	
70	        // Fetch from remote
71	        let content = self.fetch_remote(url)?;
72	
73	        // Cache the result
74	        self.save_cache(url, &content)?;
75	
76	        Ok(content)
77	    }
78	
79	    /// Fetch a configuration file, bypassing cache.
80	    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
81	        self.fetch_remote(url)
82	    }
83	
84	    /// Fetch with authentication header.
85	    ///
86	    /// Requires HTTPS to prevent credential leakage over plain HTTP.
87	    /// Returns an error if the URL scheme is not `https://`.
88	    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
89	        if !url.starts_with("https://") {
90	            return Err(anyhow!(
91	                "Refusing to send auth headers over insecure HTTP: {}. Use HTTPS instead",
92	                url
93	            ));
94	        }
95	
96	        let response = self
97	            .client
98	            .get(url)
99	            .header(&auth.header_name, &auth.header_value)
100	            .send()
101	            .with_context(|| format!("Failed to fetch {}", url))?;
102	
103	        if !response.status().is_success() {
104	            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
105	        }
106	
107	        response
108	            .text()
109	            .with_context(|| format!("Failed to read response from {}", url))
110	    }
111	
112	    fn fetch_remote(&self, url: &str) -> Result<String> {
113	        let response = self
114	            .client
115	            .get(url)
116	            .send()
117	            .with_context(|| format!("Failed to fetch {}", url))?;
118	
119	        if !response.status().is_success() {
120	            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
121	        }
122	
123	        response
124	            .text()
125	            .with_context(|| format!("Failed to read response from {}", url))
126	    }
127	
128	    fn check_cache(&self, url: &str) -> Result<Option<String>> {
129	        let cache_path = self.cache_path(url);
130	        if cache_path.exists() {
131	            let content = std::fs::read_to_string(&cache_path)?;
132	            Ok(Some(content))
133	        } else {
134	            Ok(None)
135	        }
136	    }
137	
138	    fn save_cache(&self, url: &str, content: &str) -> Result<()> {
139	        let cache_path = self.cache_path(url);
140	        if let Some(parent) = cache_path.parent() {
141	            std::fs::create_dir_all(parent)?;
142	        }
143	        std::fs::write(&cache_path, content)?;
144	        Ok(())
145	    }
146	
147	    fn cache_path(&self, url: &str) -> PathBuf {
148	        use sha2::{Digest, Sha256};
149	        let mut hasher = Sha256::new();
150	        hasher.update(url.as_bytes());
151	        let hash = hex::encode(hasher.finalize());
152	        self.cache_dir.join(format!("{}.yml", hash))
153	    }
154	
155	    /// Clear the cache for a specific URL.
156	    pub fn clear_cache(&self, url: &str) -> Result<()> {
157	        let cache_path = self.cache_path(url);
158	        if cache_path.exists() {
159	            std::fs::remove_file(&cache_path)?;
160	        }
161	        Ok(())
162	    }
163	
164	    /// Clear all cached configurations.
165	    pub fn clear_all_cache(&self) -> Result<()> {
166	        if self.cache_dir.exists() {
167	            std::fs::remove_dir_all(&self.cache_dir)?;
168	        }
169	        Ok(())
170	    }
171	
172	    /// Get the request timeout.
173	    pub fn timeout(&self) -> Duration {
174	        self.timeout
175	    }
176	}
177	
178	impl Default for RemoteFetcher {
179	    fn default() -> Self {
180	        Self::new(Duration::from_secs(30))
181	    }
182	}
