184	/// Authentication header for remote fetching.
185	#[derive(Debug, Clone)]
186	pub struct AuthHeader {
187	    /// Header name (e.g., "Authorization").
188	    pub header_name: String,
189	    /// Header value (e.g., "Bearer token123").
190	    pub header_value: String,
191	}
192	
193	impl AuthHeader {
194	    /// Create a Bearer token auth header.
195	    pub fn bearer(token: &str) -> Self {
196	        Self {
197	            header_name: "Authorization".to_string(),
198	            header_value: format!("Bearer {}", token),
199	        }
200	    }
201	
202	    /// Create a custom header auth.
203	    pub fn custom(name: impl Into<String>, value: impl Into<String>) -> Self {
204	        Self {
205	            header_name: name.into(),
206	            header_value: value.into(),
207	        }
208	    }
209	}
210	
211	/// Resolves authentication from config settings.
212	pub fn resolve_auth(
213	    auth_type: &str,
214	    token_env: &str,
215	    header: Option<&str>,
216	    env_vars: &HashMap<String, String>,
217	) -> Option<AuthHeader> {
218	    // First check the provided env_vars map, then fall back to system env
219	    let token = env_vars
220	        .get(token_env)
221	        .cloned()
222	        .or_else(|| std::env::var(token_env).ok())?;
223	
224	    match auth_type {
225	        "bearer" => Some(AuthHeader::bearer(&token)),
226	        "header" => {
227	            let header_name = header.unwrap_or("X-Auth-Token");
228	            Some(AuthHeader::custom(header_name, &token))
229	        }
230	        _ => None,
231	    }
232	}
