1	//! Cache revalidation for ETag and git strategies.
2	
3	use anyhow::Result;
4	
5	use super::{CacheEntry, CacheStore, ValidationResult};
6	use crate::registry::fetch::{GitFetcher, HttpFetcher};
7	
8	/// Performs cache revalidation using ETag or git checking.
9	pub struct CacheRevalidator<'a> {
10	    store: &'a CacheStore,
11	    http: HttpFetcher,
12	    git: GitFetcher,
13	}
14	
15	/// Result of revalidation.
16	#[derive(Debug)]
17	pub enum RevalidationResult {
18	    /// Content unchanged, cache extended.
19	    Unchanged,
20	    /// Content changed, new content available.
21	    Updated(String),
22	    /// Revalidation failed (fallback to cache or error).
23	    Failed(String),
24	}
25	
26	impl<'a> CacheRevalidator<'a> {
27	    /// Create a new revalidator.
28	    pub fn new(store: &'a CacheStore, git_clone_dir: impl Into<std::path::PathBuf>) -> Self {
29	        Self {
30	            store,
31	            http: HttpFetcher::new(),
32	            git: GitFetcher::new(git_clone_dir),
33	        }
34	    }
35	
36	    /// Revalidate an entry using its ETag.
37	    pub fn revalidate_etag(
38	        &self,
39	        url: &str,
40	        entry: &mut CacheEntry,
41	        new_ttl_seconds: u64,
42	    ) -> Result<RevalidationResult> {
43	        let etag = entry.metadata.etag.as_deref();
44	
45	        match self.http.fetch_if_changed(url, etag)? {
46	            None => {
47	                // 304 Not Modified - extend TTL
48	                entry.metadata.expires_at =
49	                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
50	                self.store.update(entry)?;
51	                Ok(RevalidationResult::Unchanged)
52	            }
53	            Some(response) => {
54	                // Content changed - update cache
55	                self.store.write_content(
56	                    &entry.source_id,
57	                    &entry.template_name,
58	                    &response.content,
59	                )?;
60	
61	                entry.metadata.etag = response.etag;
62	                entry.metadata.size_bytes = response.content.len() as u64;
63	                entry.metadata.cached_at = chrono::Utc::now();
64	                entry.metadata.expires_at =
65	                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
66	                self.store.update(entry)?;
67	
68	                Ok(RevalidationResult::Updated(response.content))
69	            }
70	        }
71	    }
72	
73	    /// Revalidate an entry using git commit comparison.
74	    pub fn revalidate_git(
75	        &self,
76	        url: &str,
77	        git_ref: Option<&str>,
78	        entry: &mut CacheEntry,
79	        new_ttl_seconds: u64,
80	    ) -> Result<RevalidationResult> {
81	        let current_sha = match &entry.metadata.commit_sha {
82	            Some(sha) => sha.clone(),
83	            None => {
84	                // No SHA to compare, must re-fetch
85	                return self.fetch_git(url, git_ref, entry, new_ttl_seconds);
86	            }
87	        };
88	
89	        let has_updates = self.git.has_updates(url, git_ref, &current_sha)?;
90	
91	        if has_updates {
92	            self.fetch_git(url, git_ref, entry, new_ttl_seconds)
93	        } else {
94	            // No updates - extend TTL
95	            entry.metadata.expires_at =
96	                chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
97	            self.store.update(entry)?;
98	            Ok(RevalidationResult::Unchanged)
99	        }
100	    }
101	
102	    /// Fetch from git and update the cache entry.
103	    fn fetch_git(
104	        &self,
105	        url: &str,
106	        git_ref: Option<&str>,
107	        entry: &mut CacheEntry,
108	        new_ttl_seconds: u64,
109	    ) -> Result<RevalidationResult> {
110	        let result = self.git.fetch(url, git_ref)?;
111	
112	        // For git sources, we store a marker that the content is at the git path
113	        let content = format!("git-path:{}", result.local_path.display());
114	        self.store
115	            .write_content(&entry.source_id, &entry.template_name, &content)?;
116	
117	        entry.metadata.commit_sha = Some(result.commit_sha);
118	        entry.metadata.cached_at = chrono::Utc::now();
119	        entry.metadata.expires_at =
